class TokenBucket {
  constructor(capacity, refillPerSec) {
    this.capacity = capacity;      // 桶容量（允许的最大突发）
    this.tokens = capacity;        // 当前令牌数
    this.refill = refillPerSec;    // 每秒补充速率
    this.last = Date.now();
  }
  allow() {
    const now = Date.now();
    this.tokens = Math.min(this.capacity,
      this.tokens + ((now - this.last) / 1000) * this.refill);
    this.last = now;
    if (this.tokens >= 1) { this.tokens -= 1; return true; }
    return false;
  }
}

function route(routes, path) {
  let best = null;
  for (const r of routes) {
    const exact = r.match === path;
    const prefix = r.match !== '/' && path.startsWith(r.match) &&
      (path.length === r.match.length || path[r.match.length] === '/');
    if (exact || prefix) {
      if (!best || r.priority > best.priority) best = r;
    }
  }
  return best ? best.svc : null;
}

const rs = [
  { match: '/api', svc: 'a', priority: 1 },
  { match: '/api/orders', svc: 'b', priority: 10 },
];
console.log(route(rs, '/api/orders'));
console.log(route(rs, '/api/users/x'));
console.log(route(rs, '/healthz'));

