class ConfigStore {
  constructor(initial) { this.data = { ...initial }; this.listeners = new Set(); }
  get(key) { return this.data[key]; }
  subscribe(fn) { this.listeners.add(fn); return () => this.listeners.delete(fn); }
  update(patch) { this.data = { ...this.data, ...patch }; for (const fn of this.listeners) fn(this.data); }
}
const cs = new ConfigStore({ featureX: false, rate: 10 });
const unsub = cs.subscribe((d) => console.log("热更新:", JSON.stringify(d)));
console.log("初始:", cs.get("featureX"));
cs.update({ featureX: true });
cs.update({ rate: 20 });
unsub();
cs.update({ featureX: false });
console.log("最终:", cs.get("featureX"));
```

