async function bffCart(userId, fetchers) {
  const [user, cart, recommendations] = await Promise.all([
    fetchers.user(userId),
    fetchers.cart(userId),
    fetchers.reco(userId),
  ]);
  return { profile: user, items: cart, suggest: recommendations };
}

